import itertools

def is_product_of_two_primes(n):
    """Checks if n is a product of exactly two distinct primes."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    return len(factors) == 2 and all(count == 1 for count in factors.values())

def is_product_of_three_primes(n):
    """Checks if n is a product of exactly three distinct primes."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    return len(factors) == 3 and all(count == 1 for count in factors.values())

