import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

products = set()
max_limit = 30 # Start with a modest limit for c

# Generate P = b * c where gcd(b, c) = 1 and b < c
for b in range(1, max_limit):
    for c in range(b + 1, 2 * max_limit): # Increase c limit slightly
        if gcd(b, c) == 1:
            products.add(b * c)

sorted_products = sorted(list(products))

if len(sorted_products) >= 20:
